import React, { useEffect, useState } from "react";
import { ShoppingCart, Search, RefreshCw } from "lucide-react";

export default function Market() {
  const [products, setProducts] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [cart, setCart] = useState([]);
  const [minPrice, setMinPrice] = useState("");
  const [maxPrice, setMaxPrice] = useState("");

  // Simulate Real-Time API Fetch
  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError(null);

      // Demo API simulation
      await new Promise((res) => setTimeout(res, 1200));

      const data = [
        {
          id: 1,
          name: "Fresh Tomatoes",
          price: 30,
          farmer: "Ramesh",
          stock: 40,
          image: "https://via.placeholder.com/300x200?text=Tomatoes",
        },
        {
          id: 2,
          name: "Organic Potatoes",
          price: 25,
          farmer: "Suresh",
          stock: 25,
          image: "https://via.placeholder.com/300x200?text=Potatoes",
        },
        {
          id: 3,
          name: "Green Chillies",
          price: 45,
          farmer: "Mahesh",
          stock: 15,
          image: "https://via.placeholder.com/300x200?text=Chillies",
        },
        {
          id: 4,
          name: "Bananas",
          price: 50,
          farmer: "Karthik",
          stock: 60,
          image: "https://via.placeholder.com/300x200?text=Bananas",
        },
      ];

      setProducts(data);
    } catch (err) {
      setError("Failed to load products");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // Add to Cart
  const addToCart = (product) => {
    const exists = cart.find((c) => c.id === product.id);

    if (exists) {
      setCart(
        cart.map((c) =>
          c.id === product.id ? { ...c, qty: c.qty + 1 } : c
        )
      );
    } else {
      setCart([...cart, { ...product, qty: 1 }]);
    }
  };

  // Filters
  const filteredProducts = products
    .filter((p) =>
      p.name.toLowerCase().includes(search.toLowerCase())
    )
    .filter((p) => (minPrice ? p.price >= minPrice : true))
    .filter((p) => (maxPrice ? p.price <= maxPrice : true));

  const cartCount = cart.reduce((sum, i) => sum + i.qty, 0);

  return (
    <div className="min-h-screen bg-gradient-to-br from-yellow-50 via-green-50 to-emerald-100 p-6">
      {/* Header */}
      <div className="max-w-7xl mx-auto mb-8">
        <div className="flex justify-between items-center mb-4 flex-wrap gap-3">
          <h2 className="text-3xl font-bold text-green-800">
            Farmer's Market
          </h2>

          {/* Cart */}
          <div className="relative">
            <ShoppingCart size={26} className="text-green-700" />
            {cartCount > 0 && (
              <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs px-2 rounded-full">
                {cartCount}
              </span>
            )}
          </div>
        </div>

        <p className="text-gray-600 mb-5">
          Live products from registered farmers
        </p>

        {/* Search & Filters */}
        <div className="bg-white shadow rounded-2xl p-4 flex flex-wrap gap-4 items-center">
          <div className="flex items-center border rounded-xl px-3 py-2 flex-1 min-w-[200px]">
            <Search size={18} className="text-gray-400 mr-2" />
            <input
              type="text"
              placeholder="Search products..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full outline-none"
            />
          </div>

          <input
            type="number"
            placeholder="Min ₹"
            value={minPrice}
            onChange={(e) => setMinPrice(e.target.value)}
            className="border rounded-xl px-3 py-2 w-28"
          />

          <input
            type="number"
            placeholder="Max ₹"
            value={maxPrice}
            onChange={(e) => setMaxPrice(e.target.value)}
            className="border rounded-xl px-3 py-2 w-28"
          />

          <button
            onClick={fetchProducts}
            className="flex items-center gap-2 bg-green-600 text-white px-4 py-2 rounded-xl hover:bg-green-700"
          >
            <RefreshCw size={16} /> Refresh
          </button>
        </div>
      </div>

      {/* Status */}
      <div className="max-w-7xl mx-auto">
        {loading && (
          <p className="text-center text-gray-500 py-10 animate-pulse">
            Loading products...
          </p>
        )}

        {error && (
          <p className="text-center text-red-500 py-10">{error}</p>
        )}
      </div>

      {/* Products */}
      {!loading && !error && (
        <div className="max-w-7xl mx-auto grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {filteredProducts.map((p) => (
            <div
              key={p.id}
              className="bg-white rounded-2xl shadow-lg overflow-hidden hover:scale-105 transition"
            >
              <img
                src={p.image}
                alt={p.name}
                className="w-full h-40 object-cover"
              />

              <div className="p-4">
                <h3 className="text-lg font-semibold">{p.name}</h3>

                <p className="text-sm text-gray-600">
                  Farmer: {p.farmer}
                </p>

                <p className="text-sm text-gray-500 mb-1">
                  Stock: {p.stock} kg
                </p>

                <p className="text-green-700 font-bold mb-3">
                  ₹{p.price} / kg
                </p>

                <button
                  disabled={p.stock === 0}
                  onClick={() => addToCart(p)}
                  className={`w-full flex items-center justify-center gap-2 py-2 rounded-xl transition text-white ${
                    p.stock === 0
                      ? "bg-gray-400 cursor-not-allowed"
                      : "bg-green-600 hover:bg-green-700"
                  }`}
                >
                  <ShoppingCart size={18} />
                  {p.stock === 0 ? "Out of Stock" : "Add to Cart"}
                </button>
              </div>
            </div>
          ))}

          {filteredProducts.length === 0 && (
            <p className="col-span-full text-center text-gray-500 mt-10">
              No products found
            </p>
          )}
        </div>
      )}
    </div>
  );
}
